There is no test covering the case where `plugin.init()` throws an error during `install()`. While `loadPlugin()` already has a "cleanup on registration failure" test for the underlying mechanism, there is no test verifying that: (1) a failed `init()` leaves the plugin in an unloaded state, and (2) a subsequent `install()` call can retry after an `init()` failure. This is especially relevant since `init()` is documented as a validation/config-loading step that could legitimately fail.
```suggestion
    });

    it('should leave plugin unloaded if init throws during install', async () => {
      const initFn = vi.fn(() => {
        throw new Error('init failed');
      });
      const startFn = vi.fn();
      const stopFn = vi.fn();

      const appPlugin = {
        name: '@test/init-failure',
        version: '1.0.0',
        type: 'app-metadata' as const,
        init: initFn,
        start: startFn,
        stop: stopFn,
      };

      await expect(pluginSystem.install(appPlugin, registry)).rejects.toThrow(
        'init failed'
      );

      expect(pluginSystem.isLoaded('@test/init-failure')).toBe(false);
      expect(startFn).not.toHaveBeenCalled();
      expect(stopFn).not.toHaveBeenCalled();
    });

    it('should allow retrying install after an init failure', async () => {
      const initFn = vi
        .fn()
        .mockImplementationOnce(() => {
          throw new Error('transient init error');
        })
        .mockImplementation(() => {
          // succeed on subsequent calls
        });

      const startFn = vi.fn();
      const stopFn = vi.fn();

      const appPlugin = {
        name: '@test/init-retry',
        version: '1.0.0',
        type: 'app-metadata' as const,
        init: initFn,
        start: startFn,
        stop: stopFn,
      };

      await expect(pluginSystem.install(appPlugin, registry)).rejects.toThrow(
        'transient init error'
      );
      expect(pluginSystem.isLoaded('@test/init-retry')).toBe(false);
      expect(startFn).not.toHaveBeenCalled();
      expect(stopFn).not.toHaveBeenCalled();

      await pluginSystem.install(appPlugin, registry, { logger: console });

      expect(initFn).toHaveBeenCalledTimes(2);
      expect(startFn).toHaveBeenCalledTimes(1);
      expect(startFn).toHaveBeenCalledWith({ logger: console });
      expect(pluginSystem.isLoaded('@test/init-retry')).toBe(true);
    });
